2. Add a routedFakeModel helper (place near scriptedIO or other test utilities):

  function routedFakeModel(routes: {
    bible: () => string | Promise<string>;
    summary: () => string | Promise<string>;
  }): ModelClient {
    return {
      complete: async (input) => {
        if (input.system?.includes('extract structured world facts')) {
          return routes.bible();
        }
        return routes.summary();
      },
    };
  }

3. Update the baseDeps default model (the field that currently reads `model: { complete: async () => 'FAKE_ARC_SUMMARY' } satisfies ModelClient`) to:

